// Official NCERT & CBSE Curriculum Database for Indian Schools (Classes 6–12)
// Follows the National Education Policy 2020 (NEP 2020) & National Curriculum Framework (NCF).
// Dual Medium support: English Medium & Hindi Medium (हिंदी माध्यम) with dedicated chapter-wise video masterclasses.

export interface IndianNCERTChapter {
  chapterNumber: number;
  slug: string;
  titleEnglish: string;
  titleHindi: string;
  ncertCode: string;
  summaryEnglish: string;
  summaryHindi: string;
  keyTopicsEnglish: string[];
  keyTopicsHindi: string[];
  englishVideo: {
    youtubeVideoId: string;
    title: string;
    channelTitle: string;
    durationFormatted: string;
  };
  hindiVideo: {
    youtubeVideoId: string;
    title: string;
    channelTitle: string;
    durationFormatted: string;
  };
}

export interface IndianSubjectCurriculum {
  classNumber: number; // 6, 7, 8, 9, 10, 11, 12
  classSlug: string; // 'grade-6', 'grade-10', etc.
  classLabel: string; // 'Class 6', 'Class 10', etc.
  subjectSlug: string; // 'mathematics', 'science', 'social-studies', 'english', 'computer-science'
  subjectNameEnglish: string;
  subjectNameHindi: string;
  boardAuthority: string;
  ncertBookEnglish: string;
  ncertBookHindi: string;
  totalChapters: number;
  chapters: IndianNCERTChapter[];
}

