export function getIndianNCERTSubjectCurriculum(
  gradeOrClassSlug: string,
  subjectSlug: string
): IndianSubjectCurriculum | undefined {
  const normGrade = gradeOrClassSlug.toLowerCase();
  const normSubject = subjectSlug.toLowerCase();

  const key = `${normGrade}:${normSubject}`;
  if (INDIAN_NCERT_CURRICULUM_DATABASE[key]) {
    return INDIAN_NCERT_CURRICULUM_DATABASE[key];
  }

  // Fallback for related science/maths subjects if exact class key isn't explicitly defined
  const matchedGrade = Object.values(INDIAN_NCERT_CURRICULUM_DATABASE).find(
    c => c.classSlug === normGrade && c.subjectSlug === normSubject
  );
  if (matchedGrade) {
    return matchedGrade;
  }

  return undefined;
}
